// Analytic, sample-measured spectra; six initialized 16-kbit BSRAMs.
// Three registered stages: table read, spectral blend multiply, final sum.
module guitar_wave_table(input clk,enable,input [23:0] phase,step,input [7:0] brightness,
 output reg signed [12:0] value=0);
 wire [1:0] band=step>=24'd368000 ? 2'd2 : step>=24'd184000 ? 2'd1 : 2'd0;
 wire [11:0] address={band,phase[23:14]};
 wire [15:0] body,attack;
 guitar_body_sp body_rom(.clk(clk),.enable(enable),.address(address),.data(body));
 guitar_attack_sp attack_rom(.clk(clk),.enable(enable),.address(address),.data(attack));
 reg [7:0] brightness_q=0;
 reg signed [12:0] body_q=0;
 reg signed [22:0] delta=0;
 wire signed [13:0] difference=$signed(attack)-$signed(body);
 always @(posedge clk)begin
  brightness_q<=brightness;body_q<=$signed(body);
  delta<=difference*$signed({1'b0,brightness_q});
  value<=body_q+($signed(delta)>>>8);
 end
endmodule
